-- ============================================================================
-- 'As-is' score import from Teacher-care's CSV exports.
--
-- IMPORTANT: this data is known to be incomplete/inconsistent and will be
-- corrected. It's loaded verbatim rather than reconciled, per instruction —
-- unlike the student roster, no attempt was made to determine a single
-- 'correct' value per student/subject/term. Where the same student+subject
-- appears in more than one source file, BOTH rows are kept (see the term_id
-- suffixes below) rather than picking one.
--
-- Student names matched against the corrected roster in
-- 001_roster_2024_2025.sql (student-directory.html, not tcc_broadsheet.html
-- — see that file's header comment for why).
--
-- Source CSVs used real different schemas per file — long format, wide
-- format with _CA/_Exam suffixes, slash-delimited 'CA/Exam/Total' in one
-- cell, pipe-delimited 'CA|Exam|Total' — parsed by scripts/parse_scores.py
-- (kept in this repo for anyone re-running this import after cleanup).
--
-- 2847 score rows loaded. 10 student
-- names in the source CSVs could not be matched to the roster and were
-- skipped (not silently dropped — listed below):
--   - Adio Daniel
--   - Fagbola Emmanualla
--   - Ilo David
--   - Ilo Joseph
--   - Makinde Aminat
--   - Olagbibi Susan
--   - Olushola Esther
--   - Oyeniran Rukibat
--   - Oyesanya Michelle
--   - Yusuf Sulaimot
-- These may be new/transferred-in students not yet added to the roster —
-- worth checking before assuming they're just typos.
-- ============================================================================

